SQL_DOC.P_SQL:
SELECT PLANT ,QUOTATION_NO ,QUOTATION_SEQ ,REVISION ,STATUS ,BUYER_ITEM_NO ,UNIT_PRICE ,AGENT ,TO_CHAR(ROWNUM,'FM00000') AS AGENT_SEQ ,BID_SUCCESS_FLAG ,REMARK ,AGENT_NAME ,SYS_DATE ,SYS_TIME FROM ( SELECT A.BUYER AS PLANT ,A.QUOTATION_NO AS QUOTATION_NO ,TO_NUMBER(A.QUOTATION_SEQ) AS QUOTATION_SEQ ,A.REVISION AS REVISION ,A.STATUS AS STATUS ,A.BUYER_ITEM_NO AS BUYER_ITEM_NO ,B.ATOB_UNIT_PRICE AS UNIT_PRICE ,B.AGENT AS AGENT ,B.BID_SUCCESS_FLAG AS BID_SUCCESS_FLAG ,NVL(SUBSTRB(ATOB_REMARK,1,100),' ') AS REMARK ,(SELECT NVL(T.COM_NAME_LOC,' ') FROM ICOMCMPY T WHERE T.COM_CODE = B.AGENT ) AS AGENT_NAME ,TO_CHAR(SYSDATE, 'YYYYMMDD') AS SYS_DATE ,TO_CHAR(SYSDATE, 'HH24MISS') AS SYS_TIME FROM KEPRQDT A, KEPQTDT B WHERE A.BUYER = '$G_RS.BUYER$' AND A.QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND A.QUOTATION_SEQ = '$G_RS.QUOTATION_SEQ$' AND A.REVISION = TO_NUMBER('$G_RS.REVISION$') AND A.BUYER = B.BUYER AND A.QUOTATION_NO = B.QUOTATION_NO AND A.QUOTATION_SEQ= B.QUOTATION_SEQ AND A.REVISION = B.REVISION AND B.STATUS = 'C' AND B.ATOB_UNIT_PRICE > 0 ORDER BY B.BID_SUCCESS_FLAG DESC, B.ATOB_UNIT_PRICE,B.AGENT )
BEGIN
UPDATE KEPRQDT SET SEND_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), SEND_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE BUYER = '$G_RS.BUYER$' AND QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND QUOTATION_SEQ = '$G_RS.QUOTATION_SEQ$' AND REVISION = TO_NUMBER('$G_RS.REVISION$') ;
UPDATE ICOMTRXL SET KEY_10 = 'D', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = '$G_RS.DOC_NAME$' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND KEY_10 IN (' ','N') ;
END;
UPDATE ICOMTRXL SET KEY_10 = 'E', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = '$G_RS.DOC_NAME$' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND KEY_10 IN (' ','N')
